function translateVideo(video,language="ta"){if(!video)return null;const isTamil=language==="ta";const title=isTamil?video.titleTamil||video.title:video.titleEnglish||video.title||video.titleTamil;const description=isTamil?video.descriptionTamil||video.description:video.descriptionEnglish||video.description||video.descriptionTamil;return{...video,title:title||"Budget Padmanaban Video",description:description||"Financial Insights by Budget Padmanaban",duration:video.duration||(video.isShort?"Short":"10:00"),views:video.views||18500,activeLang:language};}function translateNewsArticle(article,language="ta"){if(!article)return null;const isTamil=language==="ta";return{...article,title:isTamil?article.titleTamil:article.titleEnglish||article.titleTamil,summary:isTamil?article.summaryTamil:article.summaryEnglish||article.summaryTamil,content:isTamil?article.contentTamil:article.contentEnglish||article.contentTamil,activeLang:language};}async function getTrendingPreviewVideos(language="ta"){try{const res=await fetch('/api/videos/trending-preview?limit=8');if(res.ok){const json=await res.json();if(json.status==='success'&&Array.isArray(json.data)&&json.data.length>0){return json.data.map(v=>translateVideo({...v,titleTamil:v.title_ta||v.titleTamil||v.title,titleEnglish:v.title_en||v.titleEnglish||v.title,publishedAt:v.published_at||v.publishedAt},language));}}}catch(e){console.warn('Public trending preview API fallback:',e);}// Fallback to top 8 items from static preview catalog
return videosData.slice(0,8).map(v=>translateVideo(v,language));}async function getLatestVideos(language="ta",category="all",sort="newest"){try{let headers={};if(typeof window!=='undefined'&&window.supabase){try{const sessionRes=await window.supabase.auth.getSession();const token=sessionRes?.data?.session?.access_token;if(token){headers['Authorization']=`Bearer ${token}`;}}catch(e){}}const url=`/api/videos?limit=100&category=${encodeURIComponent(category)}&sort=${encodeURIComponent(sort)}`;const res=await fetch(url,{headers});if(res.ok){const json=await res.json();if(json.status==='success'&&Array.isArray(json.data)&&json.data.length>0){return json.data.map(v=>translateVideo({...v,titleTamil:v.title_ta||v.titleTamil||v.title,titleEnglish:v.title_en||v.titleEnglish||v.title,descriptionTamil:v.description_ta||v.descriptionTamil||v.description,descriptionEnglish:v.description_en||v.descriptionEnglish||v.description,publishedAt:v.published_at||v.publishedAt},language));}}}catch(e){console.warn('Using local video dataset fallback:',e);}let list=[...videosData];if(category&&category!=="all"){list=list.filter(v=>v.category===category);}if(sort==="oldest"){list.sort((a,b)=>new Date(a.publishedAt)-new Date(b.publishedAt));}else{list.sort((a,b)=>new Date(b.publishedAt)-new Date(a.publishedAt));}return list.map(v=>translateVideo(v,language));}async function getVideoById(id,language="ta"){if(!id)return null;// 1. Try local memory / static list
let video=videosData.find(v=>v.id===id||v.youtubeId===id||v.youtube_id===id);if(video){const ytId=video.youtubeId&&video.youtubeId.length===11?video.youtubeId:video.id&&video.id.length===11?video.id:'GizYMQfl9CY';return translateVideo({...video,youtubeId:ytId},language);}// 2. Try fetching from backend API
try{const res=await fetch(`/api/videos/${encodeURIComponent(id)}`);if(res.ok){const json=await res.json();if(json.status==='success'&&json.data){const v=json.data;const ytId=v.youtube_id||v.youtubeId||(v.id&&v.id.length===11?v.id:'_fvxhThYO70');return translateVideo({id:ytId,dbId:v.id,youtubeId:ytId,titleTamil:v.title_ta||v.titleTamil||v.title,titleEnglish:v.title_en||v.titleEnglish||v.title,descriptionTamil:v.description_ta||v.descriptionTamil||v.description,descriptionEnglish:v.description_en||v.descriptionEnglish||v.description,thumbnail:v.thumbnail_url||v.thumbnail||`https://img.youtube.com/vi/${ytId}/hqdefault.jpg`,duration:v.duration||'10:00',views:v.view_count||v.views||18500,publishedAt:v.published_at||v.publishedAt||new Date().toISOString(),category:v.category||'mutual-funds',tags:v.tags||[]},language);}}}catch(e){console.warn('API fetch video detail fallback:',e);}// 3. Fallback: If id is a valid 11-char YouTube ID (or fallback to latest channel video)
const is11CharYt=typeof id==='string'&&id.length===11&&!id.includes('-');const safeYtId=is11CharYt?id:'_fvxhThYO70';return translateVideo({id:safeYtId,youtubeId:safeYtId,titleTamil:'முதலீட்டு காணொளி (Budget Padmanaban)',titleEnglish:'Investment Guide Video',descriptionTamil:'YouTube இல் Budget Padmanaban வழங்கும் நிதி வழிகாட்டுதல் காணொளி.',descriptionEnglish:'Financial investment guide by Budget Padmanaban.',thumbnail:`https://img.youtube.com/vi/${safeYtId}/hqdefault.jpg`,duration:'10:00',views:24500,publishedAt:new Date().toISOString(),category:'mutual-funds',tags:['mutual-funds','personal-finance']},language);}async function getRelatedVideos(currentId,language="ta"){await new Promise(resolve=>setTimeout(resolve,30));const filtered=videosData.filter(v=>v.id!==currentId&&v.youtubeId!==currentId);return filtered.slice(0,4).map(v=>translateVideo(v,language));}function searchAllContent(query,language="ta"){if(!query||!query.trim())return[];const q=query.toLowerCase().trim();const qTerms=q.split(/\s+/).filter(Boolean);// 1. Search across all 882 videos
const matchedVideos=videosData.map(v=>{let score=0;const titleT=(v.titleTamil||v.title||"").toLowerCase();const titleE=(v.titleEnglish||v.title||"").toLowerCase();const descT=(v.descriptionTamil||v.description||"").toLowerCase();const descE=(v.descriptionEnglish||v.description||"").toLowerCase();const cat=(v.category||"").toLowerCase();const tags=(v.tags||[]).join(' ').toLowerCase();if(titleT.includes(q)||titleE.includes(q))score+=120;if(cat.includes(q)||q.includes(cat.replace('-',' ')))score+=70;if(tags.includes(q))score+=50;qTerms.forEach(term=>{if(titleT.includes(term)||titleE.includes(term))score+=30;if(descT.includes(term)||descE.includes(term))score+=15;if(tags.includes(term))score+=10;});if(score===0)return null;const translated=translateVideo(v,language);return{...translated,contentType:'video',score};}).filter(Boolean);// 2. Search across news articles
const matchedArticles=newsData.map(a=>{let score=0;const titleT=(a.titleTamil||"").toLowerCase();const titleE=(a.titleEnglish||"").toLowerCase();const sumT=(a.summaryTamil||"").toLowerCase();const sumE=(a.summaryEnglish||"").toLowerCase();const cat=(a.category||"").toLowerCase();if(titleT.includes(q)||titleE.includes(q))score+=130;if(cat.includes(q)||q.includes(cat.replace('-',' ')))score+=70;qTerms.forEach(term=>{if(titleT.includes(term)||titleE.includes(term))score+=35;if(sumT.includes(term)||sumE.includes(term))score+=20;});if(score===0)return null;const translated=translateNewsArticle(a,language);return{...translated,contentType:'article',score};}).filter(Boolean);return[...matchedArticles,...matchedVideos].sort((a,b)=>b.score-a.score);}async function searchVideos(query,language="ta"){const all=searchAllContent(query,language);return all.filter(item=>item.contentType==='video');}// ==================== 3. CONTEXTS ====================
const LanguageContext=createContext();function LanguageProvider({children}){const[language,setLanguageState]=useState(()=>localStorage.getItem("dhanavriksha_language")||"ta");const[isTranslating,setIsTranslating]=useState(false);const setLanguage=newLang=>{if(newLang===language)return;setIsTranslating(true);setLanguageState(newLang);localStorage.setItem("dhanavriksha_language",newLang);setTimeout(()=>setIsTranslating(false),200);};useEffect(()=>{document.documentElement.setAttribute("lang",language);},[language]);const t=path=>{const keys=path.split('.');let result=translations[language];for(const key of keys){if(result&&result[key]!==undefined)result=result[key];else{let fallback=translations['ta'];for(const fk of keys){if(fallback&&fallback[fk]!==undefined)fallback=fallback[fk];}return typeof fallback==='string'?fallback:path;}}return result;};return/*#__PURE__*/React.createElement(LanguageContext.Provider,{value:{language,setLanguage,t,isTranslating}},children);}const useLanguage=()=>useContext(LanguageContext);const ThemeContext=createContext();function ThemeProvider({children}){const[theme,setThemeState]=useState(()=>localStorage.getItem("dhanavriksha_theme")||"light");const toggleTheme=()=>{const nextTheme=theme==="dark"?"light":"dark";setThemeState(nextTheme);localStorage.setItem("dhanavriksha_theme",nextTheme);};useEffect(()=>{document.documentElement.setAttribute("data-theme",theme);},[theme]);return/*#__PURE__*/React.createElement(ThemeContext.Provider,{value:{theme,toggleTheme}},children);}const useTheme=()=>useContext(ThemeContext);const AuthContext=createContext();const DEFAULT_SUPABASE_URL="https://etanokdvfyvkidpeovdi.supabase.co";const DEFAULT_SUPABASE_ANON_KEY="eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6ImV0YW5va2R2Znl2a2lkcGVvdmRpIiwicm9sZSI6ImFub24iLCJpYXQiOjE3ODY2ODUxNzUsImV4cCI6MjEwMjI2MTE3NX0.SLzp5gIZyZdB7nmDrfjvghFbAwKwAIWuf4Ys_HC4AaE";// Initialize Supabase Client reliably across all environments
